#!/usr/bin/env python3
"""Deterministically emit a hand-mapped unsigned (1.f)*(1.f) compressor tree.

No synthesis mapper is involved. Every partial product is an ac_and; every
3:2 compressor is an ac_fa. Constant leading ones are connected as wires.
"""
from pathlib import Path


def generate():
    lines = ['`timescale 1ns/1ps', '`default_nettype none',
             '// Generated by scripts/generate_multiplier.py; do not edit by hand.',
             'module ac_sig11_product(input [9:0] a,b,output [21:0] p);']
    columns = [[] for _ in range(23)]
    for i in range(11):
        for j in range(11):
            if i == j == 10:
                bit = "1'b1"
            elif i == 10:
                bit = f'b[{j}]'
            elif j == 10:
                bit = f'a[{i}]'
            else:
                bit = f'pp_{i}_{j}'
                lines += [f'    wire {bit};', f'    ac_and pp{i}_{j}(a[{i}],b[{j}],{bit});']
            columns[i + j].append(bit)
    n = 0
    for k in range(22):
        while len(columns[k]) > 2:
            a, b, c = [columns[k].pop(0) for _ in range(3)]
            s, co = f's{n}', f'c{n}'
            lines += [f'    wire {s},{co};', f'    ac_fa fa{n}({a},{b},{c},{s},{co});']
            columns[k].append(s)
            columns[k + 1].append(co)
            n += 1
    carry = None
    for k in range(22):
        bits = columns[k] + ([carry] if carry else [])
        carry = None
        if len(bits) == 1:
            lines.append(f'    assign p[{k}]={bits[0]};')
        elif len(bits) == 2:
            carry = f'r{k}'
            lines += [f'    wire {carry};', f'    ac_ha ha{k}({bits[0]},{bits[1]},p[{k}],{carry});']
        elif len(bits) == 3:
            carry = f'r{k}'
            lines += [f'    wire {carry};', f'    ac_fa ripple{k}({bits[0]},{bits[1]},{bits[2]},p[{k}],{carry});']
        else:
            lines.append(f"    assign p[{k}]=1'b0;")
    assert not columns[22], columns[22]
    lines += ['endmodule', '`default_nettype wire', '']
    return '\n'.join(lines)


if __name__ == '__main__':
    target = Path(__file__).resolve().parents[1] / 'rtl/common/sig11_product.v'
    target.write_text(generate(), encoding='utf-8')
    print(target.name)
